_ZERO_DIGITS = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE_DIGITS = {"BHD", "JOD", "KWD", "OMR", "TND"}

# Link names (rejected by Meridale) and the canonical id to send instead.
_CANONICAL_ZONES = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "US/Mountain": "America/Denver",
    "US/Alaska": "America/Anchorage",
    "US/Hawaii": "Pacific/Honolulu",
    "US/Arizona": "America/Phoenix",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Asia/Katmandu": "Asia/Kathmandu",
    "Asia/Rangoon": "Asia/Yangon",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "Canada/Eastern": "America/Toronto",
    "Canada/Pacific": "America/Vancouver",
    "Japan": "Asia/Tokyo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}

_OFFSET = re.compile(r"^\s*(?:UTC|GMT)?\s*([+-\u2212])\s*(\d{1,2})(?::?(\d{2}))?\s*$", re.IGNORECASE)

_SUPPORTED_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}

NBSP = "\u00a0"
# locale -> (decimal, group, code before the number?)
_STYLE = {
    "en-US": (".", ",", True),
    "en-GB": (".", ",", True),
    "ja-JP": (".", ",", True),
    "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True),
    "de-DE": (",", ".", False),
    "es": (",", ".", False),
    "de-CH": (".", "\u2019", False),
    "fr-FR": (",", "\u202f", False),
}


def _zone(tz: str) -> str:
    """The canonical zone id to send for the zone name or fixed offset stored on the account."""
    tz = tz.strip()
    m = _OFFSET.match(tz)
    if m:
        sign, hours, minutes = m.group(1), int(m.group(2)), int(m.group(3) or 0)
        if minutes or hours > 14:
            raise ValueError(f"unsupported fixed offset {tz!r}: only whole hours exist")
        if hours == 0:
            return "Etc/UTC"
        # POSIX convention: the sign is inverted.
        return f"Etc/GMT{'-' if sign == '+' else '+'}{hours}"
    return _CANONICAL_ZONES.get(tz, tz)


def _locale(posix: str) -> str:
    """The BCP 47 tag Meridale supports that matches the account's POSIX locale."""
    name = posix.split(".")[0].split("@")[0].strip().replace("_", "-")
    parts = [p for p in name.split("-") if p]
    if not parts:
        return "en-US"
    lang = parts[0].lower()
    region = next((p.upper() for p in parts[1:] if len(p) == 2 and p.isalpha()), None)
    if region and f"{lang}-{region}" in _SUPPORTED_LOCALES:
        return f"{lang}-{region}"
    if lang in _SUPPORTED_LOCALES:
        return lang
    return "en-US"


def _digits(currency: str) -> int:
    if currency in _ZERO_DIGITS:
        return 0
    if currency in _THREE_DIGITS:
        return 3
    return 2


def _group(integer: str, locale: str) -> str:
    sep = _STYLE[locale][1]
    if locale == "es" and len(integer) == 4:
        return integer
    if locale == "en-IN":
        if len(integer) <= 3:
            return integer
        head, tail = integer[:-3], integer[-3:]
        chunks = []
        while len(head) > 2:
            chunks.insert(0, head[-2:])
            head = head[:-2]
        if head:
            chunks.insert(0, head)
        return sep.join(chunks + [tail])
    chunks = []
    while len(integer) > 3:
        chunks.insert(0, integer[-3:])
        integer = integer[:-3]
    chunks.insert(0, integer)
    return sep.join(chunks)


def _text(value: Decimal, currency: str, locale: str) -> str:
    decimal_sep, _, code_first = _STYLE[locale]
    digits = _digits(currency)
    value = value.quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)
    negative = value < 0
    plain = f"{abs(value):f}"
    integer, _, frac = plain.partition(".")
    number = _group(integer, locale) + (decimal_sep + frac if digits else "")
    if negative:
        number = "-" + number
    return f"{currency}{NBSP}{number}" if code_first else f"{number}{NBSP}{currency}"


def _amount(value: str, currency: str) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-_digits(currency)), rounding=ROUND_HALF_EVEN)
